import { useRef } from 'react';
import { PlusIcon } from '@phosphor-icons/react';
import { Button, Group, Input, Stack, Text, TextInput } from '@mantine/core';
import { FormErrors, formRootRule, isNotEmpty, useForm } from '@mantine/form';
import { randomId } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';
import { QuestionCard } from './QuestionCard';
import { createOption, createQuestion, QuestionnaireValues } from './types';

export function QuestionnaireBuilder() {
  const addQuestionRef = useRef<HTMLButtonElement>(null);
  const addOptionRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const form = useForm<QuestionnaireValues>({
    initialValues: {
      title: 'Customer satisfaction',
      questions: [
        {
          key: randomId(),
          text: 'How often do you use the product?',
          options: [createOption('Daily'), createOption('Weekly'), createOption('Rarely')],
        },
      ],
    },
    validate: {
      title: isNotEmpty('Title is required'),
      questions: {
        [formRootRule]: isNotEmpty('Add at least one question'),
        text: isNotEmpty('Question text is required'),
        options: {
          [formRootRule]: (value) => (value.length < 2 ? 'Add at least 2 options' : null),
          label: isNotEmpty('Option label is required'),
        },
      },
    },
  });

  const questions = form.useWatchValue('questions');

  const handleSubmit = (values: QuestionnaireValues) => {
    notifications.show({
      title: 'Questionnaire saved',
      message: `${values.title}: ${values.questions.length} ${values.questions.length === 1 ? 'question' : 'questions'} saved`,
    });
  };

  const getErrorNode = (path: string) => {
    if (path === 'questions') {
      return addQuestionRef.current;
    }

    const optionsList = path.match(/^questions\.(\d+)\.options$/);
    return optionsList ? addOptionRefs.current[Number(optionsList[1])] : form.getInputNode(path);
  };

  const handleErrors = (errors: FormErrors) => {
    getErrorNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <TextInput
          size="md"
          label="Questionnaire title"
          placeholder="Customer satisfaction"
          withAsterisk
          {...form.getInputProps('title')}
        />

        {questions.map((question, index) => (
          <QuestionCard
            key={question.key}
            form={form}
            index={index}
            addOptionRef={(node) => {
              addOptionRefs.current[index] = node;
            }}
          />
        ))}

        {questions.length === 0 && (
          <Text size="sm" ta="center">
            No questions yet
          </Text>
        )}

        {form.errors.questions && <Input.Error size="md">{form.errors.questions}</Input.Error>}

        <Group>
          <Button
            ref={addQuestionRef}
            variant="default"
            leftSection={<PlusIcon size={16} />}
            onClick={() => form.insertListItem('questions', createQuestion())}
          >
            Add question
          </Button>
        </Group>

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Save questionnaire
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { PlusIcon, TrashIcon } from '@phosphor-icons/react';
import { ActionIcon, Button, Group, Input, Stack, TextInput } from '@mantine/core';
import { QuestionnaireForm, createOption } from './types';

interface OptionsListProps {
  form: QuestionnaireForm;
  questionIndex: number;
  addOptionRef?: React.Ref<HTMLButtonElement>;
}

export function OptionsList({ form, questionIndex, addOptionRef }: OptionsListProps) {
  const options = form.useWatchValue(`questions.${questionIndex}.options`);

  return (
    <Stack gap="xs" pl="xl">
      {options.map((option, optionIndex) => (
        <Group key={option.key} gap="xs" wrap="nowrap" align="flex-start">
          <TextInput
            placeholder={`Option ${optionIndex + 1}`}
            aria-label={`Option ${optionIndex + 1}`}
            size="md"
            style={{ flex: 1 }}
            {...form.getInputProps(`questions.${questionIndex}.options.${optionIndex}.label`)}
          />

          <ActionIcon
            variant="default"
            size="input-md"
            aria-label="Remove option"
            onClick={() => form.removeListItem(`questions.${questionIndex}.options`, optionIndex)}
          >
            <TrashIcon size={18} color="var(--mantine-color-red-6)" />
          </ActionIcon>
        </Group>
      ))}

      {form.errors[`questions.${questionIndex}.options`] && (
        <Input.Error size="md">{form.errors[`questions.${questionIndex}.options`]}</Input.Error>
      )}

      <Group>
        <Button
          ref={addOptionRef}
          size="compact-sm"
          variant="default"
          leftSection={<PlusIcon size={14} />}
          onClick={() => form.insertListItem(`questions.${questionIndex}.options`, createOption())}
        >
          Add option
        </Button>
      </Group>
    </Stack>
  );
}

import { TrashIcon } from '@phosphor-icons/react';
import { ActionIcon, Group, Surface, Stack, TextInput } from '@mantine/core';
import { OptionsList } from './OptionsList';
import { QuestionnaireForm } from './types';

interface QuestionCardProps {
  form: QuestionnaireForm;
  index: number;
  addOptionRef?: React.Ref<HTMLButtonElement>;
}

export function QuestionCard({ form, index, addOptionRef }: QuestionCardProps) {
  return (
    <Surface level={0} withBorder p="md">
      <Stack gap="sm">
        <Group gap="xs" wrap="nowrap" align="flex-start">
          <TextInput
            size="md"
            label={`Question ${index + 1}`}
            placeholder="Type your question"
            withAsterisk
            style={{ flex: 1 }}
            {...form.getInputProps(`questions.${index}.text`)}
          />

          <ActionIcon
            variant="default"
            size="input-md"
            aria-label="Remove question"
            mt={25}
            onClick={() => form.removeListItem('questions', index)}
          >
            <TrashIcon size={18} color="var(--mantine-color-red-6)" />
          </ActionIcon>
        </Group>

        <OptionsList form={form} questionIndex={index} addOptionRef={addOptionRef} />
      </Stack>
    </Surface>
  );
}

import { UseFormReturnType } from '@mantine/form';
import { randomId } from '@mantine/hooks';

export interface Option {
  key: string;
  label: string;
}

export interface Question {
  key: string;
  text: string;
  options: Option[];
}

export interface QuestionnaireValues {
  title: string;
  questions: Question[];
}

export function createOption(label = ''): Option {
  return {
    key: randomId(),
    label,
  };
}

export function createQuestion(): Question {
  return {
    key: randomId(),
    text: '',
    options: [createOption(), createOption()],
  };
}

export type QuestionnaireForm = UseFormReturnType<QuestionnaireValues>;
